        {
            AccountId = account1Id,
            TimestampMin = cursor2 + 1,
            Limit = 2,
            Flags = AccountFilterFlags.Debits | AccountFilterFlags.Credits,
        });
        Assert.AreEqual(0, page3.Length);
    }

